import {initNaming} from './filenames.js';
import {initRepoExplorer} from './repo-explorer.js';
import {patternHTML,practiceHTML,comparisonHTML,enrichCards} from './learning.js';
import {workTreeSVG,storyTakeaway} from './work-tree.js';
import {publicationHTML,researchHTML,lossHTML,rhymeHTML,starterHTML} from './publication.js';
import {INITIAL,evaluate,demoStats} from './engine.js';
import {graphSVG,ROWS} from './graph.js';
const [data,report,manifest,maintenance,lossReport]=await Promise.all([fetch('wissen.json').then(r=>r.json()),fetch('demobericht.json').then(r=>r.json()),fetch('analysemanifest.json').then(r=>r.json()),fetch('pflegehandbuch.md').then(r=>r.text()),fetch('verlustbericht.json').then(r=>r.json())]);
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={...INITIAL};
const label=(key,value)=>data.choices.find(c=>c.key===key).options[value];
const paragraphs=ps=>ps.map(p=>`<p>${esc(p).replace(/\b(Python|XQuery)\b/,word=>`<a href="#begriff-analyse">${word}</a>`).replace(/(Close Reading|Distant Reading)/,word=>`<a href="#begriff-reading">${word}</a>`)}</p>`).join('');
const links=xs=>xs.map(([t,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)} ↗</a>`).join(' · ');
const sections=xs=>xs.map(s=>`<section class="story-part"><h4>${esc(s.title)}</h4>${paragraphs(s.paragraphs||[s.text])}</section>`).join('');
const flow=xs=>`<div class="flow">${xs.map((p,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<section>${typeof p==='string'?esc(p):`<strong>${esc(p.title)}</strong><p>${esc(p.text)}</p>`}</section>`).join('')}</div>`;
const explain=s=>`<h4>Wie hilft Git?</h4><p>${esc(s.git)}</p><h4>Handlung</h4><p>${esc(s.action)}</p><p class="question">${esc(s.question)}</p>`;
const mdHTML=raw=>raw.split(/\r?\n/).map(line=>line.startsWith('# ')?`<h2>${esc(line.slice(2))}</h2>`:line.startsWith('## ')?`<h3>${esc(line.slice(3))}</h3>`:line.startsWith('```')?'':line?`<p>${esc(line)}</p>`:'').join('');
const qualityTable=()=>`<div class="table-scroll"><table><caption>Ausgeführter Prüfbericht der künstlichen Beispiele</caption><thead><tr><th>Prüfung</th><th>Fehlerhafter Import</th><th>Korrigierter Import</th></tr></thead><tbody><tr><th>Demo-Schema</th><td>Bestanden</td><td>Bestanden</td></tr><tr><th>IDs und vorhandene Verweise</th><td>Bestanden</td><td>Bestanden</td></tr><tr><th>Rätsel / Lösungen</th><td>${report.segmentation.bad.riddles} / ${report.segmentation.bad.solutions}</td><td>${report.segmentation.corrected.riddles} / ${report.segmentation.corrected.solutions}</td></tr><tr><th>Bekannte Quellstruktur</th><td>Nicht erfüllt</td><td>Erfüllt</td></tr></tbody></table></div>`;
function segmentationHTML(print=false){return `<div class="demo"><p class="eyebrow">AUSPROBIEREN · KÜNSTLICHE BEISPIELDATEIEN</p><h4>Was ist eigentlich grün?</h4><p>Die Vorlage enthält zwei Rätsel und zwei getrennte Lösungen. Das ursprüngliche Schema erlaubt Sammlungen ohne Lösungen; es kennt diese Quelle nicht.</p>${print?'':`<div class="demo-control"><button type="button" data-segment="bad" aria-pressed="true">Fehlerhafter Import</button><button type="button" data-segment="corrected" aria-pressed="false">Korrigierter Import</button></div><div id="segment-result" class="demo-result" role="status"></div>`}${qualityTable()}<details><summary>Die Zuordnung im TEI ansehen</summary><pre><code>&lt;div type="riddle" xml:id="riddle-demo-001"&gt;
  &lt;p&gt;Ich habe Zähne und esse nicht. Was bin ich?&lt;/p&gt;
&lt;/div&gt;
&lt;!-- Lösung im getrennten Lösungsteil --&gt;
&lt;item corresp="#riddle-demo-001"&gt;Der Kamm.&lt;/item&gt;</code></pre><p>Das kleine Relax-NG-Schema und die Verweisprüfungen wurden tatsächlich ausgeführt. Diese Anzeige liest den gespeicherten Prüfbericht; sie führt keine neue XML-Prüfung im Browser aus. Ein vollständiges Korpusmodell braucht eine eigene dokumentierte TEI-Anpassung.</p></details>${flow(data.qualitySteps)}</div>`;}
function qualityHTML(print=false){return lossHTML(lossReport,print)+`<details><summary>Ein zweiter Fehler: Lösungen als Rätsel gezählt</summary>${segmentationHTML(print)}</details>`;}
const versionTable=()=>`<div class="table-scroll"><table><caption>Künstliche Bestände, keine historischen Forschungsergebnisse</caption><thead><tr><th>Auswahl</th><th>Vers</th><th>Gesamt</th><th>Anteil</th></tr></thead><tbody><tr><th>Demo-v1.0</th><td>2</td><td>4</td><td>50 %</td></tr><tr><th>Demo-v1.1</th><td>8</td><td>10</td><td>80 %</td></tr><tr><th>Demo-v1.1 · alte Belege</th><td>2</td><td>4</td><td>50 %</td></tr></tbody></table></div>`;
function versionHTML(print=false){return `<div class="demo"><p class="eyebrow">BESTAND UND AUSWAHL GETRENNT BETRACHTEN</p><h4>Was verändert die Verteilung?</h4><p>Die beiden alten Buchdateien sind in beiden Fassungen bytegleich. Die neue Fassung ergänzt ein Buch mit sechs Versrätseln.</p>${print?'':`<div class="demo-control"><label for="demo-version">Korpusfassung<select id="demo-version"><option value="v1.0">Demo-v1.0</option><option value="v1.1">Demo-v1.1</option></select></label><label for="demo-scope">Auswahl<select id="demo-scope"><option value="all">Alle Belege dieses Releases</option><option value="old">Nur die vier alten Belege</option></select></label></div><div id="version-result" class="demo-result" role="status"></div><div class="bars"><div><div class="bar-track"><span id="verse-bar" class="bar-fill"></span></div><p class="bar-caption">Versrätsel</p></div><div><div class="bar-track"><span id="prose-bar" class="bar-fill"></span></div><p class="bar-caption">Prosarätsel</p></div></div>`}${versionTable()}<details><summary>Gleiche Daten – anderer Export?</summary><p>Aus derselben korrigierten TEI-Datei liefern zwei XSLT-Auswahlen ${report.extraction.riddles_only_words} bzw. ${report.extraction.including_solutions_words} durch Leerraum getrennte Wörter. Die zweite Auswahl zählt Lösungen mit. Das ist ein technischer Demonstrationsbefund, keine historische Sprachstatistik.</p><p>Deshalb gehören Extraktionsregel, Auswahl und Werkzeugfassung zur Forschungsgrundlage.</p><pre><code>${print?esc("Vollständiges Analysemanifest: analysemanifest.json; eigenes Materialblatt Analyse."):esc(JSON.stringify(manifest,null,2))}</code></pre><p>Für diese Demonstration sind DOI und Git-Commit ausdrücklich leer. Sie ist kein fertiges Forschungszitat und keine reale Datenpublikation.</p></details>${flow(data.citationSteps)}</div>`;}
const annotationHTML=()=>`<div class="demo"><p class="eyebrow">ZUSATZANNOTATION VERÖFFENTLICHEN</p><h4>Unsere Empfehlung: eine eigene Annotationsschicht</h4><div class="annotation-ways"><section><h4>${esc(data.annotationWays[1].title)}</h4><p>${esc(data.annotationWays[1].text)}</p></section></div><p>Beispiel: Die Wortannotation 1.0 nennt Korpus v1.0 als Basis und dokumentiert ihre Tokenisierung. Die TEI-Basis bleibt separat nutzbar.</p><details><summary>Vertiefung: Wann kommt ein anderer Weg in Betracht?</summary><div class="annotation-ways">${[data.annotationWays[0],data.annotationWays[2]].map(a=>`<section><h4>${esc(a.title)}</h4><p>${esc(a.text)}</p></section>`).join('')}</div></details></div>`;
const handoverHTML=()=>`<div class="demo"><p class="eyebrow">VOM FRISCHEN DOWNLOAD ZUM EIGENEN BEFUND</p><h4>Ein Einstieg ohne Leas Rechner</h4>${starterHTML()}<h4>Was wird zusätzlich geprüft?</h4><ul><li>Ist der maßgebliche Bestand erkennbar, sind Annotationen und Ableitungen erklärt?</li><li>Funktionieren Dateinamen, relative Pfade und dokumentierte Abhängigkeiten in einer anderen Umgebung?</li><li>Sind Datenrelease, Auswahl und Verfahren im Ergebnis nachvollziehbar?</li><li>Kann eine Vertretung anhand der versionierten Pflegeanleitung einen lokalen Probe-Release erstellen?</li></ul><p>Ein erfolgreicher Nutzungseinstieg schafft noch keine unbegrenzte Pflegekapazität. Kontakt und zugesagter Pflegeumfang bleiben sichtbar.</p></div>`;
const accessHTML=()=>`<div class="flow"><section><strong>TEI + dokumentierte Exporte</strong><p>Eigenständig nutzbare Daten; für den Einstieg sind Beispiele und Anleitung nötig.</p></section><section><strong>Bibliothek oder statische Ansicht</strong><p>Erleichtert konkrete Aufgaben; Software und Beispiele müssen aktuell bleiben.</p></section><section><strong>Laufende Anwendung / API</strong><p>Zusätzlicher Zugang mit Betrieb, Sicherheit, Wartung und Support.</p></section></div>`;
const migrationHTML=()=>`<div class="two-col"><section><h4>Git-Daten</h4><p>Dateistände, Commitbeziehungen und übertragene Referenzen. Tags und benötigte Zusatzobjekte ausdrücklich prüfen.</p></section><section><h4>Zusätzlich erhalten</h4><p>Relevante Issues und Entscheidungen, Anhänge, Prüfverfahren, CI-Konfiguration, Rollen, Zugänge und Kontaktwege.</p></section></div><p class="note">Erhaltene Releases, vollständige Pakete und ein tatsächlicher Neuaufbau begrenzen Abhängigkeiten. Das Archiv ersetzt nicht automatisch einen laufenden Host.</p>`;
const demoFor=(id,print=false)=>({'P03-S01':()=>qualityHTML(print),'P03-S02':()=>versionHTML(print),'P03-S07':comparisonHTML,'P03-S03':()=>annotationHTML()+`<details class="deeper-example"><summary>Ausprobieren: Reimhinweis und Modellversuch</summary>${rhymeHTML(print)}</details>`,'P03-S04':handoverHTML,'P03-S05':accessHTML,'P03-S06':migrationHTML}[id])();
$('#persona').innerHTML=`<p class="lead">${esc(data.persona.lead)}</p>${paragraphs(data.persona.paragraphs)}<p class="question">${esc(data.persona.question)}</p>`;
$('#facts').innerHTML=Object.entries(data.persona.facts).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
$('#windows').innerHTML=data.windows.map(w=>`<section><h3>${esc(w.title)}</h3><p>${esc(w.text)}</p></section>`).join('');
$('#roles').innerHTML=data.roles.map(r=>`<section class="role"><small>${esc(r.role)}</small><h3>${esc(r.name)}</h3><p>${esc(r.text)}</p></section>`).join('');
$('#recommended-pattern').innerHTML=patternHTML(data);
$('#use-cases').innerHTML=data.uses.map(u=>`<section><h3>${esc(u.title)}</h3><p>${esc(u.text)}</p></section>`).join('');$('#research-path').innerHTML=researchHTML(data);$('#publication-concept').innerHTML=publicationHTML(data);$('#local-start').innerHTML=starterHTML();
$('#contributing').innerHTML=sections(data.contributing);$('#pipeline').innerHTML=flow(data.pipeline);
$('#glossary').innerHTML=data.glossary.map(g=>`<details id="begriff-${g.id}"><summary>${esc(g.title)}</summary>${paragraphs(g.paragraphs)}<p>${links(g.links)}</p></details>`).join('');
$('#story-nav').innerHTML=data.stories.map((s,i)=>`<a href="#${s.id}">${i+1}. ${esc(s.title)}</a>`).join('');
$('#stories').innerHTML=data.stories.map((s,i)=>`<article class="story${i>4?' story-short':''}" id="${s.id}"><div class="story-title"><p class="eyebrow">THEMA ${i+1} / ${esc(s.topic)}</p><h3>${esc(s.title)}</h3><p class="teaser">${esc(s.teaser)}</p>${s.image?`<figure class="story-picture"><img src="assets/${esc(s.image)}" alt="${esc(s.image_alt)}" loading="lazy" width="1536" height="1024"><figcaption>${esc(s.image_alt)}<span>Fiktive Szene · KI-Illustration</span></figcaption></figure>`:''}</div><div class="story-body">${sections(s.sections)}${storyTakeaway(s)}${s.id==='P03-S07'?`<figure class="work-tree">${workTreeSVG()}<figcaption>Für die eigene Studie sind die getrennten Bearbeitungsstände sinnvoll.</figcaption></figure>`:''}</div>${demoFor(s.id)}${practiceHTML(s)}<details class="discussion"><summary>Für Workshop und Selbststudium: eine Frage</summary><p>${esc(s.question)}</p></details></article>`).join('');
$('#fields').innerHTML=data.choices.map(c=>`<label for="${c.key}">${esc(c.label)}</label><select id="${c.key}" name="${c.key}">${Object.entries(c.options).map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select>`).join('');
$('#care-states').innerHTML=data.careStates.map(c=>`<section><h4>${esc(c.title)}</h4><p>${esc(c.text)}</p></section>`).join('');
const effectLabels={usability:'Können andere mit den Daten arbeiten?',host:'Hosting und Verantwortung',publication:'Publikationsgrenze und Qualität',citation:'Forschungsnachweis und Erhalt',annotation:'Neue Forschungsschichten',care:'Pflege und Nachfolge',access:'Zugang und Betrieb'};
const strategyHTML=()=>`<div class="strategy"><dl>${data.choices.map(c=>`<dt>${esc(c.label)}</dt><dd>${esc(label(c.key,state[c.key]))}</dd>`).join('')}</dl>${Object.entries(evaluate(state)).filter(([k])=>k!=='publicationAllowed').map(([k,v])=>`<h4>${effectLabels[k]}</h4><p>${esc(v)}</p>`).join('')}<h3>Verbindlicher Ausgangspunkt</h3>${sections(data.strategy)}</div>`;
const inventoryHTML=()=>`<table><thead><tr><th>Situation</th><th>Wirkung</th><th>Git und Maßnahme</th></tr></thead><tbody>${data.inventory.map(r=>`<tr><th scope="row">${esc(r.situation)}</th><td>${esc(r.effect)}</td><td>${esc(r.git)}. ${esc(r.measure)}</td></tr>`).join('')}</tbody></table>`;
$('#inventory').innerHTML=inventoryHTML();
function render(){const r=evaluate(state);for(const c of data.choices)$('#'+c.key).value=state[c.key];$('#funding').disabled=state.frontend==='no';$('#publication-gate').textContent=r.publicationAllowed?'Im gewählten Szenario: Dieses abgegrenzte Datenpaket kann nach den beschriebenen Freigaben publiziert werden.':'Im gewählten Szenario fehlt noch eine Voraussetzung für die öffentliche Freigabe.';$('#effects').innerHTML=Object.entries(effectLabels).map(([k,v])=>`<section class="effect"><h4>${v}</h4><p>${esc(r[k])}</p></section>`).join('');$('#strategy').innerHTML=strategyHTML();$('#graph').innerHTML=graphSVG(state,true);$('#graph-text').innerHTML='<ol>'+ROWS.map(row=>`<li>${esc(row.label)} ${esc(label(row.key,state[row.key]))}</li>`).join('')+'</ol><p>Alle Wege brauchen gemeinsame Regeln. Wechsel und Erweiterungen benötigen erneute Prüfung; die technische Möglichkeit ist keine Ressourcen- oder Freigabezusage.</p>';$('#risks').innerHTML=data.risks.map(x=>`<button type="button" class="risk" data-risk="${x.id}" aria-haspopup="dialog"><small>${esc(x.meaning)}</small><strong>${esc(x.title)}</strong><span>${esc(x.action)}</span><span>Beispiel &amp; Handlung öffnen ↗</span></button>`).join('');enrichCards(document,data);}
function updateSegment(key){const r=report.segmentation[key];$('#segment-result').textContent=`${r.riddles} als Rätsel gezählte Einträge, ${r.solutions} Lösungen. Schema und vorhandene Verweise: bestanden. Bekannte Quellenmerkmale: ${r.source_regression?'erfüllt':'nicht erfüllt'}.`;document.querySelectorAll('[data-segment]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.segment===key)));}
function updateDemo(){const v=$('#demo-version').value,scope=$('#demo-scope').value;const r=demoStats(report,v,scope);$('#version-result').textContent=`${r.verse} von ${r.riddles} Rätseln sind als Vers kodiert: ${r.verse_percent} %. ${scope==='old'?'Die ursprüngliche Belegauswahl bleibt gleich.':'Der vollständige Bestand dieses Releases wird verglichen.'}`;$('#verse-bar').style.width=r.verse_percent+'%';$('#prose-bar').style.width=(100-r.verse_percent)+'%';}
const materials=[['persona','Personakarte','Projekt und Rollen'],['stories','Sieben Situationen','Vollständige Lesefassung'],['decisions','Entscheidungsgraph','A3 · Wege und Konvergenzen'],['publication','Das Repo als Publikation','Konzept und Bestandsordnung'],['quality','Qualitätsprüfung','Quelle, Schema und Freigabe'],['releases','Versionen und Zitation','Releasevergleich und Manifest'],['expansions','Neue Annotationen','Drei Erweiterungswege'],['handover','Erfolg und Übergabe','Pflegepflichten und Test'],['starter','Lokal beginnen','Erste Untersuchung ohne API'],['strategy','Unsere Musterstrategie','Acht verbindliche Ausgangsentscheidungen'],['benchmark','Reime und Modellversuche','Versuch und Datenbezüge'],['risks','Chancen und Risiken','Situationen und Maßnahmen']];
$('#materials').innerHTML=materials.map(([k,title,sub])=>`<article class="material"><small>${sub}</small><h3>${title}</h3><button type="button" data-print="${k}">Drucken ↗</button><a href="assets/${k}.pdf" download>PDF herunterladen ↓</a></article>`).join('');
function printMaterial(kind){document.body.dataset.print=kind;let html='';
if(kind==='publication')html=`<h1>Das Repo als wissenschaftliche Publikation</h1>${publicationHTML(data,true)}`;
if(kind==='starter')html=`<h1>Mit dem Korpus arbeiten</h1>${starterHTML()}${researchHTML(data)}`;
if(kind==='benchmark')html=`<h1>Ein Reim hilft dem Modell?</h1>${rhymeHTML(true)}`;
if(kind==='persona')html=`<h1>Rätselhaft!</h1><p class="lead">${esc(data.subtitle)}</p>${paragraphs(data.persona.paragraphs)}<p class="question">${esc(data.persona.question)}</p><dl>${$('#facts').innerHTML}</dl><h3>Rollen</h3>${data.roles.map(r=>`<p><strong>${esc(r.name)}</strong> · ${esc(r.role)}</p>`).join('')}`;
if(kind==='stories')html=data.stories.map(s=>`<section class="card" data-story="${s.id}"><p class="eyebrow">${esc(s.topic)}</p><h1>${esc(s.title)}</h1>${sections(s.sections)}${storyTakeaway(s)}${s.id==='P03-S07'?`<figure class="work-tree">${workTreeSVG()}</figure>${comparisonHTML()}`:''}${practiceHTML(s)}</section>`).join('');
if(kind==='decisions')html=`<h1>Entscheidungswege</h1><div class="graph-print">${graphSVG(state)}</div>`;
if(kind==='architecture')html=`<h1>Vom Quelltext zum Korpus</h1>${flow(data.pipeline)}<p>Separate Werkzeugrepos liefern Konverter, Prüfungen und Analysen. Geprüfte Datenstände werden in eine eigene öffentliche Geschichte übernommen. Interne Arbeitsgeschichte wird nicht unbesehen mitpubliziert.</p>${migrationHTML()}`;
if(kind==='quality')html=`<h1>Technisch gültig – fachlich geprüft?</h1>${qualityHTML(true)}`;
if(kind==='releases')html=`<h1>Ein Ergebnis braucht seine Version</h1>${versionHTML(true)}`;
if(kind==='expansions')html=`<h1>Neue Annotation, neue Verantwortung</h1>${annotationHTML()}`;
if(kind==='handover')html=`<h1>Ohne Leas Rechner weiterarbeiten</h1>${handoverHTML()}<p>Nach Förderende wird eine klare Zusage benannt: aktive oder konservierende Pflege, Übernahme oder abgeschlossener Archivstand.</p>`;
if(kind==='maintenance')html=mdHTML(maintenance);
if(kind==='analysis')html=`<h1>Eine Forschungsgrundlage bezeichnen</h1><p>Dieses Muster benennt eine künstliche Demonstration. Für eine reale Publikation sind konkrete Versions- und Werkzeugnachweise erforderlich.</p><pre><code>${esc(JSON.stringify(manifest,null,2))}</code></pre>`;
if(kind==='scenario')html=`<h1>Vergleich: Ihre gewählte Ausgangslage</h1>${strategyHTML()}`;
if(kind==='strategy')html=`<h1>Unsere Git-Musterstrategie</h1>${patternHTML(data)}`;
if(kind==='risks')html=`<h1>Chancen, Risiken und Aufgaben</h1>${data.risks.map(r=>`<section class="risk-sheet"><h3>${esc(r.title)}</h3><p><strong>${esc(r.meaning)}</strong></p><p>${esc(r.text)}</p><p><strong>Wie hilft Git?</strong> ${esc(r.git)}</p><p><strong>Bedenken:</strong> ${esc(r.consider)}</p><p><strong>Handlung:</strong> ${esc(r.action)}</p><p><strong>Zuständig:</strong> ${esc(r.owner)}</p></section>`).join('')}`;
$('#print-root').innerHTML=`<p class="meta">EDITIONSKOMPASS · RÄTSELHAFT! · 0.4.0 · 22. Oktober 2026<br>Fiktives Projekt · Demonstrationsdaten sind künstlich · ${kind==='scenario'||kind==='decisions'?'Aktuelle Auswahl':'Eigenständig nutzbares Material'}</p>${html}`;
enrichCards($('#print-root'),data);$('#print-root').querySelectorAll('details').forEach(d=>d.open=true);let style=$('#print-size');if(!style){style=document.createElement('style');style.id='print-size';document.head.append(style);}style.textContent=`@page{size:${kind==='decisions'?'A3':'A4'} ${kind==='architecture'?'landscape':'portrait'};margin:16mm}`;window.print();}
function saveFile(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#choices').addEventListener('change',e=>{if(e.target.name){state[e.target.name]=e.target.value;render();}});$('#reset').addEventListener('click',()=>{state={...INITIAL};render();});
document.addEventListener('change',e=>{if(e.target.id==='rhyme-form')$('#rhyme-input').textContent=e.target.value==='prose'?'Prosabearbeitung: Ein Gegenstand mit Zähnen ordnet Haare. Wie heißt er?':'Zwei Verse mit Reimhinweis auf „Schlamm“.';if(e.target.id==='demo-version'||e.target.id==='demo-scope')updateDemo();});
document.addEventListener('click',e=>{const loss=e.target.closest('[data-loss]');if(loss){$('#loss-result').textContent=loss.dataset.loss==='after'?'Zwei Rätsel, keine Lösungen. Schema und Rätselzählung bestehen weiterhin; der Bestandsvergleich schlägt an.':'Zwei Rätsel und zwei Lösungen. Der bekannte Bestand ist vollständig.';document.querySelectorAll('[data-loss]').forEach(b=>b.setAttribute('aria-pressed',String(b===loss)));}const segment=e.target.closest('[data-segment]');if(segment)updateSegment(segment.dataset.segment);const n=e.target.closest('[data-key]');if(n){state[n.dataset.key]=n.dataset.value;render();$('#graph-note').textContent=label(n.dataset.key,n.dataset.value)+' gewählt. Auswahlfelder und Folgen sind aktualisiert.';document.querySelector(`[data-key="${n.dataset.key}"][data-value="${n.dataset.value}"]`)?.focus();}const p=e.target.closest('[data-print]');if(p)printMaterial(p.dataset.print);const b=e.target.closest('[data-risk]');if(b){const r=data.risks.find(r=>r.id===b.dataset.risk);$('#risk-content').innerHTML=`<h2 id="risk-title">${esc(r.title)}</h2><p><strong>${esc(r.meaning)}</strong></p><p>${esc(r.text)}</p><h4>Wie hilft Git?</h4><p>${esc(r.git)}</p><h4>Was gibt es zu bedenken?</h4><p>${esc(r.consider)}</p><h4>Handlung</h4><p>${esc(r.action)}</p><p><strong>Zuständig:</strong> ${esc(r.owner)}</p><a href="#${r.story}" id="read-story">Die zugehörige Geschichte lesen ↗</a>`;$('#risk-dialog').showModal();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.closest('[data-key]')){e.preventDefault();e.target.closest('[data-key]').dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#close-dialog').addEventListener('click',()=>$('#risk-dialog').close());$('#risk-content').addEventListener('click',e=>{if(e.target.closest('#read-story'))$('#risk-dialog').close();});
$('#download-graph').addEventListener('click',()=>saveFile(graphSVG(state),'raetsel-entscheidungen-auswahl.svg','image/svg+xml'));
$('#export').addEventListener('click',()=>saveFile('# Rätselhaft! – aktuelle Strategie\n\n'+data.choices.map(c=>'- '+c.label+': '+label(c.key,state[c.key])).join('\n')+'\n\n'+Object.entries(evaluate(state)).filter(([k])=>k!=='publicationAllowed').map(([k,v])=>'## '+effectLabels[k]+'\n\n'+v).join('\n\n'),'raetsel-strategie.md','text/markdown;charset=utf-8'));
$('#maintenance-link').href='pflegehandbuch.md';render();initNaming();initRepoExplorer();updateSegment('bad');updateDemo();window.raetsel={data,report,getState:()=>({...state}),printMaterial};
